  agentType: string;
  reviewRunId: string | null;
  lane: string | null;
  cwd: string;
  root: string;
  createdAt: string;
  deadlineAt: string;
  timeoutMs: number;
  /**
   * B-137a:F-109 — UNREACHABLE ON EVERY PATH today, retained as the carrier for
   * a future agy transport.
   *
   * An earlier note here (F-106) claimed this was "dead on the managed path but
   * live on the non-managed host_run path". That was WRONG, and F-109 corrected
   * it. The refusal in materializeLaunch (host-run.ts) throws for ANY caller
   * whose host is `agy` — managed or not — BEFORE the materializeLauncherArgv
   * call that would substitute this value. And `--print-timeout` exists only in
   * the agy launcher spec (host-execution-readiness.ts), so the codex/claude
   * callers that DO reach that substitution have no flag for it to replace.
   * The smoke previously cited as proof of liveness ("CHK-001 agy safety" in
   * host-run-usage-smoke.ts) asserts `sink.calls === 0` — it proves the runner
   * is never invoked, i.e. the opposite of liveness.
   *
   * Retained rather than deleted because it is the plumbing that carries the
   * value the day agy gains a stdin or protected prompt-file transport, at
   * which point the refusal lifts and every hop here becomes live at once.
   * Documented as unreachable so nobody mistakes it for exercised code.
   */
  agyPrintTimeout: string | null;
  projectRootHash: string;
  profile: string | null;
  reviewBinding: ManagedHostRunReviewBinding | null;
}

