   206	export function normalizeReviewerReadLog(events: readonly ReviewerReadLogEvent[]): ReviewerReadLogEvidence {
   207	  const full = new Set<string>();
   208	  const triage = new Set<string>();
   209	  const fullEvents: Array<{ path: string; mode: ReadMode; tokenCount: number | null }> = [];
   210	  const digestEvents: Array<{ path: string; mode: ReadMode; tokenCount: number | null }> = [];
   211	
   212	  for (const event of events) {
   213	    const path = normalizeRelativePath(event.path, 'readLog.event.path');
   214	    const mode = event.mode === 'triage' ? 'triage' : 'full';
   215	    const tokenCount = typeof event.tokenCount === 'number' && Number.isFinite(event.tokenCount) && event.tokenCount >= 0
   216	      ? Math.trunc(event.tokenCount)
   217	      : null;
   218	    if (mode === 'full') {
   219	      full.add(path);
   220	      fullEvents.push({ path, mode, tokenCount });
   221	    } else {
   222	      triage.add(path);
   223	    }
   224	    digestEvents.push({ path, mode, tokenCount });
   225	  }
   226	
   227	  const filesReadFully = [...full].sort((a, b) => a.localeCompare(b));
   228	  const filesTriagedByName = [...triage]
   229	    .filter(path => !full.has(path))
   230	    .sort((a, b) => a.localeCompare(b));
   231	  const hasCompleteTokenCounts = fullEvents.length > 0 && fullEvents.every(event => event.tokenCount !== null);
   232	  const tokenCount = hasCompleteTokenCounts
   233	    ? fullEvents.reduce((sum, event) => sum + (event.tokenCount ?? 0), 0)
   234	    : null;
   235	  const summary = {
   236	    readCount: fullEvents.length,
   237	    tokenCount,
   238	  };
   239	  const normalizedDigestEvents = digestEvents.sort((a, b) =>
   240	    `${a.mode}:${a.path}:${a.tokenCount ?? 'null'}`.localeCompare(`${b.mode}:${b.path}:${b.tokenCount ?? 'null'}`),
   241	  );
   242	  const digest = digestCanonicalJson({
   243	    version: 1,
   244	    filesReadFully,
   245	    filesTriagedByName,
   246	    summary,
   247	    events: normalizedDigestEvents,
   248	  });
   249	  return { filesReadFully, filesTriagedByName, summary, digest };
   250	}
