   407	  let start = -1;
   408	  let inString = false;
   409	  let escaped = false;
   410	  for (let i = 0; i < text.length; i += 1) {
   411	    const ch = text[i];
   412	    if (inString) {
   413	      if (escaped) escaped = false;
   414	      else if (ch === '\\') escaped = true;
   415	      else if (ch === '"') inString = false;
   416	      continue;
   417	    }
   418	    if (ch === '"') {
   419	      inString = true;
   420	      continue;
   421	    }
   422	    if (ch === '{') {
   423	      if (depth === 0) start = i;
   424	      depth += 1;
   425	    } else if (ch === '}') {
   426	      if (depth > 0) {
   427	        depth -= 1;
   428	        if (depth === 0 && start >= 0) {
   429	          objects.push({ text: text.slice(start, i + 1), start, end: i + 1 });
